import React, { forwardRef } from 'react';

import { RangeLegendItemLabel } from './RangeLegendItemLabel.js';
import { LABEL_ALIGNMENT, RANGE_SORTING } from '../constants.js';
import { useScale } from '../context/RangeLegendScaleContext.js';
import type { RangeItem } from '../types/range-legend.js';

interface RangeLegendAnchorItemLabelProps {
  items: RangeItem[];
  index: number;
  offset?: number;
  isDivergentPoint?: boolean;
}

export const RangeLegendAnchorItemLabel = forwardRef<
  SVGTextElement,
  RangeLegendAnchorItemLabelProps
>(({ items, index, offset = 0, isDivergentPoint }, forwarderdRef) => {
  const { scale, sorting } = useScale();

  const currentItem = items[index];
  const isFirstItem = index === 0;
  const isLastItem = index === items.length - 1;
  const startingRange = sorting === RANGE_SORTING.ASC ? 'from' : 'to';
  const divergentStartingRange = sorting === RANGE_SORTING.ASC ? 'to' : 'from';

  const startPosition = scale(currentItem[startingRange])! + offset;

  const sizeBaseDivergentPoint = isDivergentPoint
    ? scale(items[index + 1][divergentStartingRange])!
    : 0;
  const sizeBaseAnchorPoints = scale(currentItem[divergentStartingRange])!;
  const sizeBase = isDivergentPoint
    ? sizeBaseDivergentPoint
    : sizeBaseAnchorPoints;
  const size = sizeBase + offset - startPosition;

  const labelAlignment = isLastItem
    ? LABEL_ALIGNMENT.END
    : isFirstItem
    ? LABEL_ALIGNMENT.START
    : LABEL_ALIGNMENT.CENTER;

  const labelText = isLastItem
    ? currentItem[divergentStartingRange].toString()
    : currentItem[startingRange].toString();

  return (
    <RangeLegendItemLabel
      ref={forwarderdRef}
      startPosition={startPosition}
      itemSegmentSize={size}
      text={labelText}
      alignment={labelAlignment}
    />
  );
});
